// for the scheme elephc prepends.
$c2 = fsockopen("tcp://127.0.0.1", $port);
$m2 = stream_get_meta_data($c2);
var_dump($m2["uri"] === "tcp://127.0.0.1:" . $port, $m2["stream_type"]);
fclose($c2);
fclose($srv);
$p = sys_get_temp_dir() . "/elephc_fsm.sock";
@unlink($p);
$s2 = stream_socket_server("unix://" . $p);
$c3 = fsockopen("unix://" . $p);
$m3 = stream_get_meta_data($c3);
var_dump($m3["uri"] === "unix://" . $p, $m3["stream_type"]);
fclose($c3); fclose($s2); @unlink($p);
''')
